## Tier 3: Production Hardening (30 minutes)

**Add comprehensive testing, monitoring dashboards, and incident response automation.**

### Complete Test Suite

```java
package com.example.billing;

import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.test.context.support.WithMockUser;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest
@AutoConfigureMockMvc
class InvoiceSecurityTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private InvoiceRepository invoiceRepository;

    @Test
    @WithMockUser(username = "user1", authorities = "USER")
    void testUserCanAccessOwnInvoice() throws Exception {
        // Setup: Create invoice owned by user1
        Invoice invoice = new Invoice();
        invoice.setUserId(1L);
        invoice.setFilePath("/invoices/invoice1.pdf");
        invoiceRepository.save(invoice);

        mockMvc.perform(get("/api/billing/invoice/download")
                .param("invoiceId", invoice.getId().toString()))
            .andExpect(status().isOk())
            .andExpect(header().string("Content-Disposition", containsString("attachment")));
    }

    @Test
    @WithMockUser(username = "user1", authorities = "USER")
    void testUserCannotAccessOtherUsersInvoice() throws Exception {
        // Setup: Create invoice owned by user2
        Invoice invoice = new Invoice();
        invoice.setUserId(2L);  // Different user
        invoice.setFilePath("/invoices/invoice2.pdf");
        invoiceRepository.save(invoice);

        // Attempt to access as user1
        mockMvc.perform(get("/api/billing/invoice/download")
                .param("invoiceId", invoice.getId().toString()))
            .andExpect(status().isNotFound());  // Should get 404, not 200
    }

    @Test
    @WithMockUser(username = "user1", authorities = "USER")
    void testCannotBypassWithUserIdParameter() throws Exception {
        Invoice invoice = new Invoice();
        invoice.setUserId(2L);
        invoiceRepository.save(invoice);

        // Attempt to add userId parameter (should be ignored)
        mockMvc.perform(get("/api/billing/invoice/download")
                .param("invoiceId", invoice.getId().toString())
                .param("userId", "2"))  // Malicious parameter
            .andExpect(status().isNotFound());  // Parameter ignored, access denied
    }

    @Test
    @WithMockUser(username = "user1", authorities = "USER")
    void testRateLimitEnforcement() throws Exception {
        Invoice invoice = new Invoice();
        invoice.setUserId(1L);
        invoiceRepository.save(invoice);

        // Make 100 requests (should succeed)
        for (int i = 0; i < 100; i++) {
            mockMvc.perform(get("/api/billing/invoice/download")
                    .param("invoiceId", invoice.getId().toString()))
                .andExpect(status().isOk());
        }

        // 101st request should be rate limited
        mockMvc.perform(get("/api/billing/invoice/download")
                .param("invoiceId", invoice.getId().toString()))
            .andExpect(status().isTooManyRequests())
            .andExpect(header().exists("Retry-After"));
    }

    @Test
    @WithMockUser(username = "user1", authorities = "USER")
    void testEnumerationDetection() throws Exception {
        // Attempt to access 10 non-existent invoices (enumeration attack)
        for (long i = 1000L; i < 1010L; i++) {
            mockMvc.perform(get("/api/billing/invoice/download")
                    .param("invoiceId", String.valueOf(i)))
                .andExpect(status().isNotFound());
        }

        // Verify security logging captured enumeration attempt
        // Verify alert was sent to security team
        verify(securityAlertService).sendAlert(argThat(alert -> 
            alert.getSeverity().equals("HIGH") && 
            alert.getType().equals("ENUMERATION_ATTACK")
        ));
    }

    @Test
    void testUnauthenticatedAccessDenied() throws Exception {
        mockMvc.perform(get("/api/billing/invoice/download")
                .param("invoiceId", "123"))
            .andExpect(status().isUnauthorized());
    }
}
```

